/** Require the deployment boundary before choosing any child-launch path; session mode never disables it. */
export function requiredConfinement(ctx: Context, policy: unknown): {
  provider: Pick<SandboxProvider, 'confine'>
  policy: SandboxPolicy
} {
  const provider = ctx.get('aukoraConfinement')
  if (provider === undefined || typeof provider.confine !== 'function') {
    throw new HarnessError('AUKORA_CONFINEMENT_REQUIRED: required native confinement is unavailable; child startup refused', 'AUKORA_CONFINEMENT_REQUIRED')
  }
  if (policy === null || typeof policy !== 'object' || Array.isArray(policy)) {
    throw new HarnessError('AUKORA_CONFINEMENT_POLICY: a resolved confined policy is required; child startup refused', 'AUKORA_CONFINEMENT_POLICY')
  }
  const input = policy as Partial<SandboxExecutionPolicy>
  const mode = input.mode
  if ((mode !== 'read-only' && mode !== 'workspace-write') || typeof input.workspaceRoot !== 'string' || input.workspaceRoot.length === 0) {
    throw new HarnessError('AUKORA_CONFINEMENT_POLICY: read-only or workspace-write with a workspaceRoot is required; child startup refused', 'AUKORA_CONFINEMENT_POLICY')
  }
  return { provider, policy: { ...input, mode, workspaceRoot: input.workspaceRoot } }
}

